# Test Cases: 
# Most frequent: days = ['AUSJEKWAGKWIEWJAKWIEWAKSJDJD']
# Ranking: Weather (W): 3 Deicing (D): 1 Crew Timeout (C): 0 Mechanical (M): 0 
#   Ground Stop (G): 0 Gate Conflict (P): 0 
# For a tie: days = ['AUSJEKWAGKWIEDJAKWIEWAKSJDJD'] 
# Ranking: Weather (W): 2 Deicing (D): 2 Crew Timeout (C): 0 Mechanical (M): 0 
#   Ground Stop (G): 0 Gate Conflict (P): 0 
#   Connecting-Flight Backup (B): 0 Software/Scheduling System (S): 0
# For one 2/8: days = ['AUSJEKDAGKWIEDJAKWIEPAKSJDJP'] 
# Ranking: Deicing (D): 2 Gate Conflict (P): 2
#   Weather (W): 0 Crew Timeout (C): 0 Mechanical (M): 0 
#   Ground Stop (G): 0 Connecting-Flight Backup (B): 0 Software/Scheduling System (S): 0
# For two days: days = ['AUSJEKWAGKWIEDJAKWIEWAKSJDJD', 'AUSJEKWAGKWIEDJAKWIEWAKSJDJD']
#   Ranking: Weather (W): 4 Deicing (D): 4 Crew Timeout (C): 0 Mechanical (M): 0 
#   Ground Stop (G): 0 Gate Conflict (P): 0 
causes = []
counts = []
day_list = []
for day in days:
    for string_i in range(0, len(day), 7):
        day_list.append(day[string_i:string_i+7])

for day in day_list:
    index = -1
    if day[-1] in causes:
        index = causes.index(day[-1])
    else:
        causes.append(day[-1])
        counts.append(0)
    counts[index] += 1


for i in range(1, len(counts)):
    current = counts[i]
    name = causes[i]
    j = i-1

    while j >= 0 and current > counts[j]:
        temp = causes[j+1]
        causes[j+1] = causes[j]
        causes[j] = temp
        
        temp = counts[j+1]
        counts[j+1] = counts[j]
        counts[j] = temp
                
        j -= 1

    causes[j+1] = name
    counts[j+1] = current

total = sum(counts)
print(f"Total records processed: {total}")

print("Disruption ranking (most to least frequent):")
num = 1; printed = [0 for _ in range(8)]
for cause in causes:
    match cause:
        case "W": print(f"{num}. Weather ", end = ""); printed[0] = 1
        case "C": print(f"{num}. Crew Timeout ", end = ""); printed[1] = 1
        case "M": print(f"{num}. Mechanical ", end = ""); printed[2] = 1
        case "G": print(f"{num}. Ground Stop ", end = ""); printed[3] = 1
        case "D": print(f"{num}. Deicing ", end = ""); printed[4] = 1
        case "P": print(f"{num}. Gate Conflict ", end = ""); printed[5] = 1
        case "B": print(f"{num}. Connecting-Flight Backup ", end = ""); printed[6] = 1
        case "S": print(f"{num}. Software/Scheduling System ", end = ""); printed[7] = 1
    print(f"({cause}): {counts[num-1]}")
    num += 1

weather_types = ["Weather (W)", "Crew Timeout (C)", "Mechanical (M)", "Ground Stop (G)", "Deicing (D)", "Gate Conflict (P)", 
                "Connecting-Flight Backup (B)", "Software/Scheduling System (S)"]
for i in range(8):
    if printed[i] == 0:
        print(f"{num}. {weather_types[i]}: 0")
        num += 1
    
